if(!UnityEditor.EditorApplication.isPlaying)throw new System.Exception("Play mode required.");
var scenes=new[]{"PrismbloomLevel01","GloamthorneLevel02","Ashpetal Level 03","Boss"};var clips=new[]{"VeinrootHollow_Loop","GloamthornCanopy_Loop","AshpetalForest_Loop","DreadcrownForest_Loop"};
var results=new System.Collections.Generic.List<string>();int index=0,phase=0,sample=0;double deadline=0;UnityEngine.AudioSource current=null,previous=null;bool oldBackground=UnityEngine.Application.runInBackground;UnityEngine.Application.runInBackground=true;UnityEngine.Time.timeScale=1;UnityEngine.AudioListener.pause=false;
UnityEditor.EditorApplication.CallbackFunction tick=null;
void Finish(string error){UnityEditor.EditorApplication.update-=tick;UnityEngine.AudioListener.pause=false;UnityEngine.Application.runInBackground=oldBackground;results.Add(error==null?"PASS: all four scene sources tested with normal Unity/audio callbacks":"FAIL: "+error);System.IO.File.WriteAllLines("Temp/GameLoopMusicResults.txt",results);}
void Load(){previous=current;current=null;UnityEditor.SceneManagement.EditorSceneManager.LoadSceneInPlayMode("Assets/Scenes/GameLoop/"+scenes[index]+".unity",new UnityEngine.SceneManagement.LoadSceneParameters(UnityEngine.SceneManagement.LoadSceneMode.Single));phase=0;deadline=UnityEditor.EditorApplication.timeSinceStartup+.5;}
void Check(bool condition,string message){if(!condition)throw new System.Exception(scenes[index]+": "+message);}
tick=()=>{if(UnityEditor.EditorApplication.timeSinceStartup<deadline)return;try{
 if(!UnityEditor.EditorApplication.isPlaying){Finish("Play mode exited before completion");return;}
 if(phase==0){var sources=UnityEngine.Object.FindObjectsByType<UnityEngine.AudioSource>();Check(sources.Length==1,"Unexpected source count "+sources.Length);current=sources[0];Check(previous==null,"Previous music survived scene unload");Check(current.clip!=null&&current.clip.name==clips[index],"Wrong track");Check(current.isPlaying,"Autoplay did not start");Check(current.loop&&current.spatialBlend==0,"Loop/2D configuration");Check(UnityEngine.Object.FindObjectsByType<UnityEngine.AudioListener>().Count(l=>l.enabled)==1,"Expected one active listener");sample=current.timeSamples;phase=1;deadline=UnityEditor.EditorApplication.timeSinceStartup+.4;}
 else if(phase==1){Check(current.timeSamples>sample,"Playback cursor did not advance");UnityEngine.AudioListener.pause=true;sample=current.timeSamples;phase=2;deadline=UnityEditor.EditorApplication.timeSinceStartup+.2;}
 else if(phase==2){sample=current.timeSamples;phase=5;deadline=UnityEditor.EditorApplication.timeSinceStartup+.2;} else if(phase==5){Check(UnityEngine.AudioListener.pause&&System.Math.Abs(current.timeSamples-sample)<=256,"Music cursor continued during listener pause: "+(current.timeSamples-sample));UnityEngine.AudioListener.pause=false;phase=3;deadline=UnityEditor.EditorApplication.timeSinceStartup+.3;}
 else if(phase==3){Check(current.isPlaying&&current.timeSamples>sample,"Music did not resume");current.time=current.clip.length-.12f;phase=4;deadline=UnityEditor.EditorApplication.timeSinceStartup+.5;}
 else{Check(current.isPlaying&&current.time<2f,"Music failed to wrap at loop end");results.Add(scenes[index]+": correct track, autoplay/advancing cursor, one listener/source, pause/resume, loop wrapping, previous-source cleanup passed.");index++;if(index==scenes.Length)Finish(null);else Load();}
}catch(System.Exception e){Finish(e.Message);}};
UnityEditor.EditorApplication.update+=tick;Load();return "Scheduled native-frame music checks; results in Temp/GameLoopMusicResults.txt";

